import React from 'react';
import { useParams, useNavigate } from 'react-router-dom';

function Product() {
  const { id } = useParams();
  const navigate = useNavigate();

  const handleGoBack = () => {
    navigate(-1);
  };

  return (
    <div style={{ padding: '20px' }}>
      <h1>Product Details</h1>
      <p>Product ID: {id}</p>
      <button onClick={handleGoBack} style={{ padding: '8px 16px', marginTop: '10px' , cursor: 'pointer' }}>
        Go Back
      </button>
    </div>
  );
};

export default Product;
